617	    Scheduler *sch;
618	    int ret;
619	
620	    sch = av_mallocz(sizeof(*sch));
621	    if (!sch)
622	        return NULL;
623	
624	    sch->class    = &scheduler_class;
625	    sch->sdp_auto = 1;
626	
627	    ret = pthread_mutex_init(&sch->schedule_lock, NULL);
628	    if (ret)
629	        goto fail;
630	
631	    ret = pthread_mutex_init(&sch->mux_ready_lock, NULL);
632	    if (ret)
633	        goto fail;
634	
635	    ret = pthread_mutex_init(&sch->finish_lock, NULL);
636	    if (ret)
637	        goto fail;
638	
639	    ret = pthread_cond_init(&sch->finish_cond, NULL);
640	    if (ret)
641	        goto fail;
642	
643	    return sch;
644	fail:
645	    sch_free(&sch);
646	    return NULL;
647	}
