1844	
1845	        av_assert0(enc->sq_idx[0] >= 0);
1846	        sq = &sch->sq_enc[enc->sq_idx[0]];
1847	
1848	        pthread_mutex_lock(&sq->lock);
1849	
1850	        sq_frame_samples(sq->sq, enc->sq_idx[1], ret);
1851	
1852	        pthread_mutex_unlock(&sq->lock);
1853	    }
1854	
1855	    return 0;
1856	}
