2738	        pthread_mutex_unlock(&sch->finish_lock);
2739	    }
2740	
2741	    if (ret < 0)
2742	        av_log(task->func_arg, AV_LOG_ERROR,
2743	               "Terminating thread with error: %s\n", av_err2str(ret));
2744	    else
2745	        av_log(task->func_arg, AV_LOG_VERBOSE,
2746	               "Terminating thread with success\n");
2747	
2748	    return (void*)(intptr_t)ret;
2749	}
