  3491	            av_assert0(o == FRAME_OPAQUE_SEND_COMMAND && fgt.frame->buf[0]);
  3492	
  3493	            fc = (FilterCommand*)fgt.frame->buf[0]->data;
  3494	            send_command(fg, fgt.graph, fc->time, fc->target, fc->command, fc->arg,
  3495	                         fc->all_filters);
