  3509	            ret = check_reinit(fg, &fgt);
  3510	            if (ret >= 0)
  3511	                ret = send_frame(fg, &fgt, ifilter, fgt.frame, ret);
  3512	        } else {
  3513	            av_assert1(o == FRAME_OPAQUE_EOF);
  3514	            ret = send_eof(&fgt, ifilter, fgt.frame->pts, fgt.frame->time_base);
