  3548	    for (unsigned i = 0; i < fg->nb_outputs; i++) {
  3549	        OutputFilterPriv *ofp = ofp_from_ofilter(fg->outputs[i]);
  3550	
  3551	        if (fgt.eof_out[i] || !fgt.graph)
  3552	            continue;
  3553	
  3554	        ret = fg_output_frame(ofp, &fgt, NULL);
  3555	        if (ret < 0)
  3556	            goto finish;
  3557	    }
